async function handle(job) {
  const done = await db.markIfNew(job.idempotencyKey);   // 이미 처리했으면 false
  if (!done) return;
  await sendEmail(job.to, job.body);
}

await queue.add('email', payload, {
  attempts: 5,
  backoff: { type: 'exponential', delay: 1000 },   // 1s, 2s, 4s …
  removeOnComplete: 1000,
});
// 끝내 실패한 것은 DLQ(죽은 편지함)로 보내 사람이 본다
